const tls = require('tls');

// ---------- 1. Cert expiry: raw TLS handshake, no HTTP node needed ----------
// ponytail: the etcd ADMIN client cert named in the SSOT (expires 2027-07-12)
// lives only as a local file on hippodamus, not reachable over the network --
// that one is checked by etcd-snapshot.sh itself, not here. This leg covers
// what's actually fetchable: kube-apiserver, Proxmox and AD LDAPS certs.
// Not here: Talos apid :50000 (leaf auto-rotates daily, would always read <30d);
// pfSense GUI + PBS (pfSense rules block them).
const certTargets = [
  {label:'anaximander-cp1 kube-apiserver', host:'10.20.130.10', port:6443},
  {label:'anaximander-cp2 kube-apiserver', host:'10.20.130.11', port:6443},
  {label:'anaximander-cp3 kube-apiserver', host:'10.20.130.12', port:6443},
  {label:'thales-01 proxmox',        host:'10.20.110.11', port:8006},
  {label:'thales-02 proxmox',        host:'10.20.110.12', port:8006},
  {label:'thales-03 proxmox',        host:'10.20.110.13', port:8006},
  {label:'timaeus ldaps',            host:'10.20.120.10', port:636},
  {label:'simmias ldaps',            host:'10.20.120.11', port:636},
  {label:'traefik *.thales.internal',   host:'10.20.130.100', port:443},
];

function checkCert(host, port) {
  return new Promise((resolve) => {
    let done = false;
    const sock = tls.connect({host, port, rejectUnauthorized:false, timeout:8000}, () => {
      const cert = sock.getPeerCertificate();
      done = true; sock.end();
      if (!cert || !cert.valid_to) { resolve({error:'no cert returned'}); return; }
      const daysLeft = Math.floor((new Date(cert.valid_to) - Date.now()) / 86400000);
      resolve({validTo: cert.valid_to, daysLeft});
    });
    sock.on('error', (e) => { if (!done) resolve({error: e.message}); });
    sock.on('timeout', () => { if (!done) { sock.destroy(); resolve({error:'timeout'}); } });
  });
}

const certResults = [];
for (const t of certTargets) certResults.push({...t, ...(await checkCert(t.host, t.port))});
const certUrgent = certResults.filter(r => typeof r.daysLeft === 'number' && r.daysLeft < 30);
const certLines = certResults.map(r => r.error
  ? `  ⚠️ ${r.label} (${r.host}) — unreachable: ${r.error}`
  : `  ${r.daysLeft < 30 ? '🔴' : '🟢'} ${r.label} — ${r.daysLeft}d left (${r.validTo})`);

// ---------- 2. Backup freshness via Proxmox storage/content --
// PBS's own REST API is unreachable from this pod (confirmed empirically);
// Proxmox proxies the same backup listing and IS reachable, so use that. ----------
const grab = (nodeName, fallback) => {
  try {
    const j = $(nodeName).first().json;
    return (j && j.error === undefined) ? j : fallback;
  } catch (e) { return fallback; }
};

const inv = grab('Get guest inventory', {});
const guests = Array.isArray(inv.data) ? inv.data : [];

const backupNodeNames = ['Get backups thales-01', 'Get backups thales-02', 'Get backups thales-03'];
const allBackups = [];
for (const n of backupNodeNames) {
  const d = grab(n, {});
  if (Array.isArray(d.data)) allBackups.push(...d.data);
}

const now = Date.now() / 1000;
const backupLines = [];
let staleCount = 0;
for (const g of guests) {
  if (!g.vmid) continue;
  const hits = allBackups.filter(b => Number(b.vmid) === Number(g.vmid));
  const newest = hits.length ? Math.max(...hits.map(b => b.ctime || 0)) : 0;
  const ageHrs = newest ? Math.round((now - newest) / 3600) : null;
  if (!newest || ageHrs > 48) {
    staleCount++;
    backupLines.push(`  🔴 ${g.name || g.vmid} (vmid ${g.vmid}) — ${newest ? `last backup ${ageHrs}h ago` : 'no backup found'}`);
  }
}
const backupSummary = staleCount
  ? `${staleCount} of ${guests.length} guests have no backup in the last 48h:\n${backupLines.join('\n')}`
  : `all ${guests.length} guests backed up within the last 48h.`;

// ---------- 2b. K8s PVC images (k8s-rbd-backup.sh on thales-02 -> PBS ns k8s) --
// PVE's PBS listing hides host-type backups and PBS :8007 is unreachable from
// this pod, so the script leaves a marker in thales-02's node description. ----------
const marker = String((grab('Get k8s-rbd marker', {}).data || {}).description || '');
const kOk = Number((marker.match(/last_ok=(\d+)/) || [])[1] || 0);
const kFail = Number((marker.match(/last_fail=(\d+)/) || [])[1] || 0);
const kGroups = (marker.match(/groups=(\d+)/) || [])[1] || '?';
const kAge = kOk ? Math.round((now - kOk) / 3600) : null;
const k8sBackupLine = !kOk
  ? '  🔴 K8s PVCs — no k8s-rbd-backup marker on thales-02'
  : (kAge > 26 || kFail > kOk)
    ? `  🔴 K8s PVCs — last ok ${kAge}h ago${kFail > kOk ? ', latest run FAILED' : ''} (journalctl -u k8s-rbd-backup on thales-02)`
    : `  🟢 K8s PVCs — ${kGroups} volumes, last ok ${kAge}h ago`;

// ---------- 3. Drift vs SSOT: substring presence-check, deliberately a --
// smoke alarm, not a full markdown parser (per plan). ----------
const ssotRaw = (() => { try { return $('Get SSOT').first().json.data || ''; } catch (e) { return ''; } })();

const nsData = grab('Get k8s namespaces', {});
const liveNamespaces = (nsData.items || []).map(i => i.metadata.name);
const m = ssotRaw.match(/\*\*K8s namespaces\*\*:\s*(.+)/);
const docNamespaces = m ? m[1].split(',').map(s => s.split('(')[0].trim().replace(/\.$/, '')) : [];
const alwaysPresent = ['default', 'kube-public', 'kube-node-lease'];
const nsMissing = liveNamespaces.filter(n => !docNamespaces.includes(n) && !alwaysPresent.includes(n));
const nsStale = docNamespaces.filter(n => n && !liveNamespaces.includes(n));

const nodesData = grab('Get k8s nodes', {});
const liveNodeIPs = (nodesData.items || []).flatMap(i => (i.status && i.status.addresses || [])
  .filter(a => a.type === 'InternalIP').map(a => a.address));
const nodeIPsNotInSSOT = liveNodeIPs.filter(ip => ssotRaw && !ssotRaw.includes(ip));

const guestsNotInSSOT = guests.filter(g => g.name && ssotRaw && !ssotRaw.includes(g.name));

const driftLines = [];
if (nsMissing.length) driftLines.push(`  live namespace not in SSOT list: ${nsMissing.join(', ')}`);
if (nsStale.length) driftLines.push(`  SSOT lists namespace not seen live: ${nsStale.join(', ')}`);
if (nodeIPsNotInSSOT.length) driftLines.push(`  live node IP not found anywhere in SSOT text: ${nodeIPsNotInSSOT.join(', ')}`);
if (guestsNotInSSOT.length) driftLines.push(`  Proxmox guest name not found anywhere in SSOT text: ${guestsNotInSSOT.map(g => `${g.name} (vmid ${g.vmid})`).join(', ')}`);
const driftSummary = driftLines.length ? driftLines.join('\n') : 'no drift detected (namespaces, node IPs, guest names all found in the SSOT text).';

// ---------- assemble ----------
const urgentBlock = certUrgent.length
  ? `🚨 **URGENT — cert expiring soon**\n${certUrgent.map(c => `  ${c.label}: ${c.daysLeft}d left`).join('\n')}\n\n`
  : '';

const message = [
  urgentBlock + '**THALES weekly audit**',
  '',
  '**Certs**',
  certLines.join('\n'),
  '',
  '**Backups (last 48h, via Proxmox storage listing)**',
  backupSummary,
  k8sBackupLine,
  '',
  '**Drift vs SSOT**',
  driftSummary,
].join('\n').slice(0, 1900);

return [{ json: { message } }];
